INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(19701, 'Ezekiel 16:54', 'Ezekiel', 16, 54, '&nbsp;نو تۀ به په خپل شرم رسوا شې او په خپلو کړو به وشرميږې. سدوم او سامريه به خوشحاله شى چې هغوئ ستا په شان ګناهګار نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19702, 'Ezekiel 16:55', 'Ezekiel', 16, 55, '&nbsp;او ستا خوېندې، سدوم او د هغې لوڼه او سامريه او د هغې لوڼه، او تۀ او ستا لوڼه، به بيا دوباره په هغه حالت شئ لکه څنګه چې ټول د اول نه وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19703, 'Ezekiel 16:56', 'Ezekiel', 16, 56, '&nbsp;د خپلې مغرورتيا په ورځو کښې تا خپلې خور سدوم پورې خندا کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19704, 'Ezekiel 16:57', 'Ezekiel', 16, 57, '&nbsp;خو اوس ستا بدعملونه ټولې دُنيا ته څرګند شول. اوس تۀ په خپله په شرمونو کښې پټه شوې او ادوم او د هغوئ ګاونډيان او فلستيان ستا نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19705, 'Ezekiel 16:58', 'Ezekiel', 16, 58, '&nbsp;تۀ به د خپلې عياشۍ او حرام کارونو سزا وزغمې، مالِک خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19706, 'Ezekiel 16:59', 'Ezekiel', 16, 59, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، ”زۀ به تا سره هغه شان سلوک وکړم د کوم چې تۀ حقدار يې، ځکه چې د لوظ په ماتولو سره تا د قسم خوړلو سپکاوے وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19707, 'Ezekiel 16:60', 'Ezekiel', 16, 60, '&nbsp;خو ما ته لا تر اوسه پورې هغه لوظ ياد دے کوم چې ما تا سره ستا د ځوانۍ په ورځو کښې کړے وو، او زۀ به تا سره ابدى لوظ وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19708, 'Ezekiel 16:61', 'Ezekiel', 16, 61, '&nbsp;نو تۀ به خپل هغه بد عملونه راياد کړې کوم چې تا کړى دى او په هغې به شرمنده شې کله چې تۀ خپلې مشرې او کشرې خوېندې سره مِلاو شې. زۀ به تا ته هغوئ لکه د لوڼو په شان درکړم خو په دې بنياد نۀ چې تا په لوظ عمل کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19709, 'Ezekiel 16:62', 'Ezekiel', 16, 62, '&nbsp;نو زۀ به خپل لوظ تا سره تازه کړم، نو تۀ به په دې پوهه شې چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19710, 'Ezekiel 16:63', 'Ezekiel', 16, 63, '&nbsp;کله چې زۀ ستا ټول کارونه تا ته معاف کړم کوم چې تا کړى دى، نو تا ته به دا ګناهونه ياد وى او په هغې به دومره شرمېږې چې بيا به يې نوم په خولۀ نۀ اخلې، مالِک قادر مطلق خُدائ داسې فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19711, 'Ezekiel 17:1', 'Ezekiel', 17, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19712, 'Ezekiel 17:2', 'Ezekiel', 17, 2, '&nbsp;”اے بنى آدمه، بنى اِسرائيل قوم ته يو مثال پېش کړه او يو متل ورته ووايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19713, 'Ezekiel 17:3', 'Ezekiel', 17, 3, '&nbsp;هغوئ ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې، د طاقتورو وزرو او د اوږدو او رنګينه بڼو والا غټ باز لبنان ته راغلو. هغۀ د دِيار لوړه څوکه راونيوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19714, 'Ezekiel 17:4', 'Ezekiel', 17, 4, '&nbsp;هغۀ ځان سره د دې د سر نه کچه څانګه راپرې کړه او د سوداګرو مُلک ته يې يوړه، کومه چې هغۀ هلته د سوداګرو په ښار کښې وکَرله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19715, 'Ezekiel 17:5', 'Ezekiel', 17, 5, '&nbsp;هغۀ ستا د مُلک نه دا بوټے راواخستو او په زرخيزه زمکه کښې يې وکَرلو. هغۀ دا لکه د خارولى په شان د روانو اوبو په غاړه وکَرلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19716, 'Ezekiel 17:6', 'Ezekiel', 17, 6, '&nbsp;نو هغه راوټوکېدو او په زمکه لکه د انګور د بوټى په شان خور شو. د دې څانګې د هغۀ طرف ته اوږدې شوې، خو جرړې يې لاندې په زمکه کښې پاتې شوې. نو دا لکه د انګورو د ونې په شان شوه او نوې څانګې يې پېدا کړې او په پاڼو پټه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19717, 'Ezekiel 17:7', 'Ezekiel', 17, 7, '&nbsp;خو يو بل غټ باز وو چې طاقتور وزرونه يې وُو او په بڼو پټ وُو. هغه د انګور بوټے هغه ځائ نه چرته چې کَرلے شوے وو خپلې جرړې او څانګې د اوبو دپاره هغۀ ته وراوږدې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19718, 'Ezekiel 17:8', 'Ezekiel', 17, 8, '&nbsp;هغه په ښۀ خاوره کښې د ډېرو اوبو په خوا کښې کَرلے شوے وو چې څانګې وکړى، مېوه ونيسى او يو شاندار بوټے ترې جوړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19719, 'Ezekiel 17:9', 'Ezekiel', 17, 9, '&nbsp;هغوئ ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې، ولې دا بوټے به کامياب شى څۀ؟ ولې دا به د جرړو نه راونۀ باسى څۀ؟ او ولې هغه به د مېوو نه خالى نۀ کړى څۀ؟ د هغۀ ټولې څانګې به وچې شى. د دې د راويستلو دپاره د طاقتور لاس او ډېرو کسانو ضرورت نشته چې د جرړو نه يې راوباسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19720, 'Ezekiel 17:10', 'Ezekiel', 17, 10, '&nbsp;کۀ څۀ هم چې دا بل ځائ وکرلے شى، ولې دا به کامياب شى څۀ؟ ولې دا به بلکل اوچ نۀ شى کله چې د مشرق بادونه دا ووهى؟ دا به په هغه پټى کښې اوچ نۀ شى چرته چې را لوئ شوے وو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19721, 'Ezekiel 17:11', 'Ezekiel', 17, 11, '&nbsp;بيا د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19722, 'Ezekiel 17:12', 'Ezekiel', 17, 12, '&nbsp;”دې سرکشه قوم ته ووايه چې، تاسو په دې نۀ پوهېږئ چې د دې مثال څۀ مطلب دے؟ هغوئ ته ووايه چې، د بابل بادشاه يروشلم ته لاړو او د هغې بادشاه او سپين روبى يې بوتلل، او د خپل ځان سره يې بابل ته راوستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19723, 'Ezekiel 17:13', 'Ezekiel', 17, 13, '&nbsp;بيا هغۀ د شاهى خاندان نه يو کس خوښ کړو، او د هغۀ سره يې لوظ وکړو او د وفادارۍ قسم يې ترې نه واخستلو. هغۀ د ځان سره د مُلک مشران هم بوتلى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19724, 'Ezekiel 17:14', 'Ezekiel', 17, 14, '&nbsp;نو چې د هغوئ بادشاهت کمزورے شى چې بيا د سر اوچتولو قابل نۀ شى. نو دغه شان اِسرائيل به په خپلې وفادارۍ ژوندى پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19725, 'Ezekiel 17:15', 'Ezekiel', 17, 15, '&nbsp;خو د يهوداه بادشاه د هغۀ په خلاف بغاوت وکړو چې هغۀ خپل قاصدان مِصر ته ولېږل او هلته نه يې آسونه او لوئ لښکر راوستو. ولې هغه به کامياب شى؟ ولې څوک چې داسې کارونه وکړى بچ به شى؟ ولې هغه به د لوظ په ماتولو د تکليف نه خلاص شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19726, 'Ezekiel 17:16', 'Ezekiel', 17, 16, '&nbsp;مالِک قادر مطلق خُدائ فرمائى چې، زما دې په خپل ذات قسم وى، هغه به د بابل په مُلک کښې مړ شى، د هغه بادشاه په مُلک کښې چا چې هغه په تخت کښېنولے وو، د چا قسم ته چې هغۀ سپک وکتل او چې د چا لوظ يې مات کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19727, 'Ezekiel 17:17', 'Ezekiel', 17, 17, '&nbsp;فِرعون به د خپلو تکړه سپاهيانو او غټو لښکرو سره په جنګ کښې د هغۀ مدد ونۀ کړى، کله چې دشمن د ښار محاصره وکړى او د حملې دپاره د خاورو غونډۍ جوړې کړى د دې دپاره چې ډېر خلق تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19728, 'Ezekiel 17:18', 'Ezekiel', 17, 18, '&nbsp;هغۀ د لوظ په ماتولو سره د قسم سپکاوے وکړو، ځکه چې هغۀ د لوظ دپاره خپل لاس ورکړو او اوس يې دا ټول کارونه وکړل نو هغه به بچ نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19729, 'Ezekiel 17:19', 'Ezekiel', 17, 19, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى چې، زما دې په خپل ذات قسم وى، چې هغۀ زما لوظ مات کړو او زما قسم ته يې سپک وکتل نو زۀ به د خپل هغه قسم نقصان د هغۀ په سر راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19730, 'Ezekiel 17:20', 'Ezekiel', 17, 20, '&nbsp;زۀ به د هغۀ دپاره خپل جال خور کړم، او هغه به زما په دام کښې راګېر شى. زۀ به هغه بابل ته راولم او خپل قضاوت به هلته په هغۀ باندې وکړم ځکه چې هغه ما سره بې‌وفائى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19731, 'Ezekiel 17:21', 'Ezekiel', 17, 21, '&nbsp;د هغۀ د ټولو نه تکړه فوجيان به په تُوره مړۀ شى. او بچ پاتې شوى به په هوا کښې خوارۀ شى. نو بيا به تۀ په دې پوهه شې چې ما مالِک خُدائ دا فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19732, 'Ezekiel 17:22', 'Ezekiel', 17, 22, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، ”زۀ به په خپله د دِيار د لوړې څوکې نه يوه څانګه راواخلم او هغه به وکرم، زۀ به يوه نازکه څانګه د يو لوَړ دِيار د څوکې نه راپرې کړم او هغه به په يو لوړ او اوچت غر وکرم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19733, 'Ezekiel 17:23', 'Ezekiel', 17, 23, '&nbsp;زۀ به يې د اِسرائيل په اوچتو غرونو وکرم، هغه به څانګې وکړى او مېوه به ونيسى او هغه به يو شاندار دِيار شى. هر قسمه مرغۍ به په کښې جالې جوړې کړى، او هغوئ به د دې د څانګو سورې کښې پناه اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19734, 'Ezekiel 17:24', 'Ezekiel', 17, 24, '&nbsp;په زمکه کښې ټولې ونې به په دې پوهه شى چې زۀ مالِک خُدائ لوړه ونه لاندې کوم او ټيټه ونه زۀ لوړه کړم. زۀ شنه ونه اوچوم او اوچه ونه زۀ تازه او شنه کوم. ما مالِک خُدائ داسې وفرمائيل او زۀ به داسې وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19735, 'Ezekiel 18:1', 'Ezekiel', 18, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19736, 'Ezekiel 18:2', 'Ezekiel', 18, 2, '&nbsp;”ستاسو خلقو د اِسرائيل د مُلک په حقله د دې متل د وئيلو نه څۀ مطلب دے چې وائى، تراوۀ انګور يې پلار وخوړل، او غاښونه يې د بچو په برېښ شُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19737, 'Ezekiel 18:3', 'Ezekiel', 18, 3, '&nbsp;زما دې په خپل ذات قسم وى مالِک قادر مطلق خُدائ فرمائى چې، تاسو به په اِسرائيل کښې نور دا متل ونۀ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19738, 'Ezekiel 18:4', 'Ezekiel', 18, 4, '&nbsp;ځکه چې هر ژوندے ځان زما دے، پلار او د هغۀ زوئ دواړه يو شان زما دى. څوک چې ګناه وکړى هم هغه به مړ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19739, 'Ezekiel 18:5', 'Ezekiel', 18, 5, '&nbsp;کۀ يو صادق سړے هغه څۀ کوى څۀ چې صحيح وى او د اِنصاف په مطابق وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19740, 'Ezekiel 18:6', 'Ezekiel', 18, 6, '&nbsp;نۀ هغه د غرونو دپاسه په بُت‌خانو کښې خوراک کوى او نۀ د بنى اِسرائيلو د قوم د بُتانو عبادت کوى او نۀ هغۀ د خپل ګاونډى د ښځې سره زنا کوى، او نۀ د ماهوارۍ په دوران کښې د ښځې سره کوروالے کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19741, 'Ezekiel 18:7', 'Ezekiel', 18, 7, '&nbsp;هغه په هيچا باندې ظلم نۀ کوى، او په امانت کښې خيانت نۀ کوى او هغه پوره واپس کوى. هغه غلا نۀ کوى، خو خپل خوراک په غريبانانو تقسيموى او بربنډو له جامې ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19742, 'Ezekiel 18:8', 'Ezekiel', 18, 8, '&nbsp;هغه قرض د سود دپاره نۀ ورکوى او ناروا ګټه هم نۀ کوى، بدو کارونو نه ځان ساتى او د دوو کسانو په لانجه کښې د صحيح اِنصاف فېصله کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19743, 'Ezekiel 18:9', 'Ezekiel', 18, 9, '&nbsp;هغه زما د قانون پيروى کوى او په وفادارۍ سره زما قانون منى، هم دا کس صادق دے هغه به په يقين سره ژوندے پاتې شى، مالِک قادر مطلق خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19744, 'Ezekiel 18:10', 'Ezekiel', 18, 10, '&nbsp;نو بيا فرض کړئ چې د دۀ يو ظالم زوئ دے چې هغه قتل و غارت او نور داسې خراب کارونه هم کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19745, 'Ezekiel 18:11', 'Ezekiel', 18, 11, '&nbsp;پلار يې داسې کارونه نۀ وُو کړى چې زوئ يې کوى. هغه د غرونو دپاسه په بُت‌خانو کښې هم خوراک کوى او د خپل ګاونډى د ښځې سره زنا هم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19746, 'Ezekiel 18:12', 'Ezekiel', 18, 12, '&nbsp;هغه په غريبانانو او ضرورتمندو ظلم کوى او غلاګانې کوى. او هغه چې ضمانت واخلى بيا يې نۀ واپس کوى، او هغه د بُتانو عبادت کوى او حرامکارى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19747, 'Ezekiel 18:13', 'Ezekiel', 18, 13, '&nbsp;هغه په سود پېسې ورکوى او ډېره زياته ګټه اخلى. آيا داسې کس به ژوندے پاتې شى څۀ؟ نه هغه به پاتې نۀ شى. ځکه چې هغۀ دا ټول حرام کارونه وکړل، په يقين سره هغه به مړ شى او د هغۀ خون به د هغۀ د خپلې غاړې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19748, 'Ezekiel 18:14', 'Ezekiel', 18, 14, '&nbsp;خو فرض کړئ چې د دې زوئ يې يو زوئ وى څوک چې د خپل پلار ټول ګناهونه وينى، کۀ څۀ هم چې هغه دا وينى خو بيا هم هغه د خپل پلار غوندې کارونه نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19749, 'Ezekiel 18:15', 'Ezekiel', 18, 15, '&nbsp;هغه په غرونو د بُت‌خانو خوراک نۀ خورى، او نۀ د بنى اِسرائيل د قوم د بُتانو عبادت کوى، او نۀ هغه د خپل ګاونډى د ښځې سره زنا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19750, 'Ezekiel 18:16', 'Ezekiel', 18, 16, '&nbsp;هغه نۀ په چا ظلم کوى، او په امانت کښې خيانت نۀ کوى، هغه غلا نۀ کوى خو خپل خوراک په غريبانانو تقسيموى او بربنډو له جامې ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19751, 'Ezekiel 18:17', 'Ezekiel', 18, 17, '&nbsp;هغه خپل لاس په بدو کارونو نۀ پليتوى او سود نۀ اخلى او په ګټه پېسې نۀ ورکوى، هغه زما په شريعت عمل کوى او زما د تعليماتو پيروى کوى. داسې سړے به د خپل پلار د ګناه په وجه مړ نۀ شى، يقيناً به هغه ژوندے پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19752, 'Ezekiel 18:18', 'Ezekiel', 18, 18, '&nbsp;بلکې د هغۀ پلار به ضرور د خپلو ګناهونو دپاره مړ شى، ځکه چې هغۀ ظلم کولو، د خپلو وروڼو نه يې غلا کوله او هغه کارونه يې کول کوم چې د هغۀ د قوم په مينځ کښې غلط وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19753, 'Ezekiel 18:19', 'Ezekiel', 18, 19, '&nbsp;خو بيا تاسو تپوس کوئ چې زوئ يې ولې د خپل پلار په جرم کښې شريک نۀ دے؟ ځکه چې زوئ يې هغه څۀ کړى دى څۀ چې صحيح دى او د اِنصاف په مطابق دى او زما په حکمونو په وفادارۍ سره عمل کوى، هغه به يقيناً ژوندے پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19754, 'Ezekiel 18:20', 'Ezekiel', 18, 20, '&nbsp;کوم کس چې ګناه وکړى هم هغه کس به مړ شى. زوئ به د پلار په ګناه نۀ شى نيولے، او نۀ به پلار د زوئ په ګناه کښې نيولے شى. د صادق انسان صداقت به هغۀ ته په نېکۍ کښې حساب شى، او بدعمله ته به د بدعملۍ سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19755, 'Ezekiel 18:21', 'Ezekiel', 18, 21, '&nbsp;خو کۀ يو بدعمله کس د خپلو ټولو ګناهونو نه مخ واړوى کوم چې هغۀ کړى دى او زما په ټول قانون عمل وکړى او هغه کارونه کوى څۀ چې د اِنصاف او صحيح وى، نو په يقين سره به هغه ژوندے پاتې شى، هغه به مړ نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19756, 'Ezekiel 18:22', 'Ezekiel', 18, 22, '&nbsp;هغه ګناهونه چې د هغۀ نه شوى دى يو به هم د هغوئ خلاف نۀ حسابوم. د هغه ښۀ کارونو په وجه کوم چې هغوئ کړى دى، هغوئ به ژوندى پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19757, 'Ezekiel 18:23', 'Ezekiel', 18, 23, '&nbsp;مالِک قادر مطلق خُدائ فرمائى چې، ولې تاسو دا سوچ کوئ چې زۀ د شريرانو په هلاکت خوشحالېږم؟ بلکل نه، زۀ غواړم چې هغه د خپلو خرابو لارو نه واوړى او ژوندے پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19758, 'Ezekiel 18:24', 'Ezekiel', 18, 24, '&nbsp;خو کۀ چرې يو صادق انسان د خپلو نېکو کارونو نه واوړى او ګناه وکړى او حرام کارونه وکړى کوم چې يو بدعمله کس کوى ولې هغه به ژوندے پاتې شى؟ يو صادق کار به يې هم حساب نۀ شى کوم چې هغۀ کړى دى. د هغه بې‌ايمانۍ په وجه کومه چې هغۀ کړې ده او کوم ګناهونه يې چې کړى دى د هغې په بدله کښې به هغه مړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19759, 'Ezekiel 18:25', 'Ezekiel', 18, 25, '&nbsp;خو بيا تاسو وايئ چې، د مالِک خُدائ کارونه د اِنصاف نۀ دى، اے د بنى اِسرائيل قومه، ما ته غوږ شئ، آيا تاسو دا خيال کوئ چې زما کارونه بې‌اِنصافه دى؟ خو دا ستاسو عملونه دى چې بې‌اِنصافه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19760, 'Ezekiel 18:26', 'Ezekiel', 18, 26, '&nbsp;کۀ چرې يو صادق انسان خپل صداقت پرېږدى او ګناهونه شروع کړى، هغه به د دې په وجه مړ شى. د هغه ګناهونو په وجه کوم چې هغۀ وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19761, 'Ezekiel 18:27', 'Ezekiel', 18, 27, '&nbsp;خو کۀ چرې يو بدعمله انسان د خپلو ګناهونو نه واوړى کوم چې هغۀ کړى دى او هغه څۀ کوى چې صحيح او د اِنصاف په مطابق دى، هغه به خپل ‎ژوند بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19762, 'Ezekiel 18:28', 'Ezekiel', 18, 28, '&nbsp;کۀ هغه په خپلو ګناهونو غور وکړى او هغه پرېږدى کوم چې هغۀ کړى دى، نو يقيناً به هغه ژوندے پاتې شى او مړ به نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19763, 'Ezekiel 18:29', 'Ezekiel', 18, 29, '&nbsp;خو د بنى اِسرائيلو قوم وائى چې د مالِک خُدائ کارونه د اِنصاف نۀ دى. اے د بنى اِسرائيل قومه، ولې زما کارونه بې‌اِنصافه دى؟ ولې ستاسو کارونه بې‌اِنصافه نۀ دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19764, 'Ezekiel 18:30', 'Ezekiel', 18, 30, '&nbsp;نو په دې وجه، اے د بنى اِسرائيلو قومه، زۀ به ستاسو د هر يو کس د اعمالو په مطابق ستاسو عدالت وکړم، مالِک قادر مطلق خُدائ فرمائى. توبه وباسئ. د خپلو ټولو ګناهونو نه واوړئ، نو بيا به ګناه ستا د هلاکت سبب نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19765, 'Ezekiel 18:31', 'Ezekiel', 18, 31, '&nbsp;خپلو ټولو ګناهونو ته شا کړئ کوم چې تاسو کړى دى، او په خپل ځان کښې نوے زړۀ او نوے روح پېدا کړئ. تاسو ولې مړ کېدل غواړئ، اے د بنى اِسرائيل قومه؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19766, 'Ezekiel 18:32', 'Ezekiel', 18, 32, '&nbsp;زۀ د هيچا په هلاکت نۀ خوشحالېږم، مالِک قادر مطلق خُدائ فرمائى. توبه وباسئ او ژوندى پاتې شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19767, 'Ezekiel 19:1', 'Ezekiel', 19, 1, '&nbsp;د اِسرائيل د شهزادګانو په حقله دا مرثيه ووايه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19768, 'Ezekiel 19:2', 'Ezekiel', 19, 2, '&nbsp;ستا مور د زمرو په مينځ کښې څۀ تکړه زمرۍ وه، هغه د ځوانانو زمرو په مينځ کښې پرته وه او خپل بچى يې لوئ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19769, 'Ezekiel 19:3', 'Ezekiel', 19, 3, '&nbsp;هغې خپل يو بچے لوئ کړو، او د هغۀ نه يو تکړه زمرے جوړ شو. هغۀ د ښکار کولو طريقه زده کړه، او انسانان يې خوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19770, 'Ezekiel 19:4', 'Ezekiel', 19, 4, '&nbsp;مُلکونو د هغۀ په حقله واورېدل، او هغه يې په کنده کښې ګېر کړو. هغوئ هغه پېزوانى د مِصر مُلک ته بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19771, 'Ezekiel 19:5', 'Ezekiel', 19, 5, '&nbsp;خو کله چې هغې خپل اُميد نامکمله وليدلو، د هغې طمع ختمه شوه، هغې خپل بل بچے راواخستو او د هغۀ نه يې يو تکړه زمرے جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19772, 'Ezekiel 19:6', 'Ezekiel', 19, 6, '&nbsp;هغه د نورو زمرو په مينځ کښې ډاډه ګرځېدو راګرځېدو، ځکه چې هغۀ نه يو تکړه زمرے جوړ شوے وو. هغۀ د ښکار کولو طريقه زده کړه، او انسانان به يې هم خوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19773, 'Ezekiel 19:7', 'Ezekiel', 19, 7, '&nbsp;هغۀ د هغوئ قلعې ماتې کړې او د هغوئ ښارونه يې تباه کړل. هغه مُلک او ټول هغه کسان چې په کښې اوسېدل د هغۀ د غړمبېدو نه يرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19774, 'Ezekiel 19:8', 'Ezekiel', 19, 8, '&nbsp;نو بيا د هغۀ نه ګېرچاپېره مُلکونو نه قومونه د هغۀ خلاف راغلل. هغوئ خپل جال د هغۀ دپاره خور کړو، او هغه د هغوئ په کنده کښې راګېر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19775, 'Ezekiel 19:9', 'Ezekiel', 19, 9, '&nbsp;هغوئ هغه پېزوانى کړے راښکلو او په پنجره کښې يې بند کړو او هغه يې د بابل بادشاه له راوستو. هغوئ هغه په قېدخانه کښې واچولو، ترڅو چې نور د اِسرائيل په غرونو د هغۀ غړمبېدل وانۀ ورېدلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19776, 'Ezekiel 19:10', 'Ezekiel', 19, 10, '&nbsp;ستاسو مور ستاسو د انګورو باغ کښې لکه د انګور د بوټى په شان وه چې د اوبو په سر کَرلے شوې وه. د ډېرو اوبو په وجه هغه مېوه داره او د څانګو نه ډکه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19777, 'Ezekiel 19:11', 'Ezekiel', 19, 11, '&nbsp;د هغې څانګې مضبوطې وې، او د بادشاهانو د امساګانو جوړولو دپاره جوګه وې. دا د نورو ګڼو بوټو نه ډېره زياته اوچته شوه، او د خپل ګڼوالى او اوچتوالى په وجه د هر چا په نظر راتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19778, 'Ezekiel 19:12', 'Ezekiel', 19, 12, '&nbsp;خو په غصه کښې دا د جرړو نه راوويستلے شوه او په زمکه وغورزولے شوه. د مشرق هواګانو دا مړاوې کړه، دا د مېوو نه خالى شوه، د دې مضبوطې څانګې وچې شوې، او اور هغه وسوزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19779, 'Ezekiel 19:13', 'Ezekiel', 19, 13, '&nbsp;نو اوس دا په بيابان کښې په اوچه او تږې زمکه کښې وکرلے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19780, 'Ezekiel 19:14', 'Ezekiel', 19, 14, '&nbsp;اور د دې د يو خاص څانګې نه خور شو، او د دې مېوه يې وسوزوله. يوه مضبوطه څانګه په کښې پاتې نۀ شوه چې د بادشاه د امسا جوړولو جوګه وى. دا د غم يوه مرثيه ده، او د مرثيه په توګه استعمال شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19781, 'Ezekiel 20:1', 'Ezekiel', 20, 1, '&nbsp;د اوؤم کال، د پينځمې مياشتې په لسمه ورځ، د اِسرائيل يو څو مشران راغلل او زما په وړاندې کښېناستل او د خپل ځان په حقله يې زما نه د مالِک خُدائ د پېغام تپوس وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19782, 'Ezekiel 20:2', 'Ezekiel', 20, 2, '&nbsp;نو د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19783, 'Ezekiel 20:3', 'Ezekiel', 20, 3, '&nbsp;”اے بنى آدمه، د اِسرائيل د مشرانو سره خبرې وکړه او ورته ووايه چې، مالِک قادر مطلق خُدائ داسې فرمائى، آيا تاسو راغلى يئ چې زما نه معلومات حاصل کړئ؟ زما دې په خپل ذات قسم وى، زۀ به تاسو ته معلومات درنۀ کړم. قادر مطلق مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19784, 'Ezekiel 20:4', 'Ezekiel', 20, 4, '&nbsp;اے بنى آدمه، ولې تۀ غواړې چې د هغوئ عدالت وکړې؟ نو کۀ تۀ داسې کوې نو بيا هغوئ ته د هغوئ د پلار نيکۀ حرام کارونه وروښايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19785, 'Ezekiel 20:5', 'Ezekiel', 20, 5, '&nbsp;او هغوئ ته ووايه چې، مالِک قادر مطلق خُدائ داسې فرمائى، په کومه ورځ چې ما بنى اِسرائيل غوره کړل، ما د يعقوب د اولاد سره قسم وکړو او خپل ځان مې هغوئ ته په مِصر کښې ښکاره کړو. په قسم سره ما هغوئ ته وفرمائيل، زۀ ستاسو مالِک خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19786, 'Ezekiel 20:6', 'Ezekiel', 20, 6, '&nbsp;په هغه ورځ ما هغوئ سره قسم وکړو چې زۀ به هغوئ د مِصر نه هغې زمکې ته راولم کومه چې ما هغوئ دپاره خوښه کړې ده، هغه زرخيزه مُلک ته کوم چې د ټولو مُلکونو نه ډېر ښکلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19787, 'Ezekiel 20:7', 'Ezekiel', 20, 7, '&nbsp;او ما هغوئ ته ووئيل چې، تاسو ټول هغه پليت بُتان د خپلې مخې نه اخوا کړئ کوم چې تاسو د خپلو سترګو د وړاندې اېښى دى، او خپل ځانونه د مِصر په بُتانو مۀ پليتوئ. زۀ ستاسو مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19788, 'Ezekiel 20:8', 'Ezekiel', 20, 8, '&nbsp;خو هغوئ زما خلاف سرکشى وکړه او ما ته يې غوږ ونۀ نيولو، او يو هم د خپلو بُتانو نه لاس وانۀ خستو په کومو چې د هغوئ توجو وه، او نۀ هغوئ د مِصر بُتان پرېښودل. بيا ما ووئيل، زۀ به خپل غضب په هغوئ نازل کړم او زۀ به خپله غصه د هغوئ خلاف په مِصر کښې سړه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19789, 'Ezekiel 20:9', 'Ezekiel', 20, 9, '&nbsp;خو بيا، د دې په وجه ما د خپل نوم د خاطره هغه څۀ وکړل څۀ چې به هغوئ د هغه قومونو د وړاندې د سپکوالى نه وساتى د چا په مينځ کښې چې دوئ اوسېدل او د چا په وړاندې چې ما خپل ځان بنى اِسرائيلو ته د مِصر نه په راويستلو ښکاره کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19790, 'Ezekiel 20:10', 'Ezekiel', 20, 10, '&nbsp;نو په دې وجه هغوئ ما د مِصر نه راوويستل او بيابان ته مې راوستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19791, 'Ezekiel 20:11', 'Ezekiel', 20, 11, '&nbsp;ما هغوئ له خپل حُکمونه ورکړل او خپل قانون مې هغوئ ته وښودلو، هر څوک چې په دې عمل کوى نو هغوئ به ژوندى پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19792, 'Ezekiel 20:12', 'Ezekiel', 20, 12, '&nbsp;ما ورته د سبت ورځ هم ورکړه چې دا زمونږ دواړو په مينځ کښې د لوظ نښه وى، نو چې هغوئ په دې پوهه شى چې ما مالِک خُدائ دوئ مقدس کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19793, 'Ezekiel 20:13', 'Ezekiel', 20, 13, '&nbsp;خو د بنى اِسرائيلو خلقو په صحرا کښې هم زما خلاف سرکشى وکړه. هغوئ زما په حکمونو عمل ونۀ کړو او زما شريعت يې رد کړو، او دا چې چا هم په دې عمل وکړو هغه به په دې ژوندى پاتې شى. خو هغوئ په ښکاره توګه زما د سبت بې‌عزتى وکړه. نو ما وفرمائيل چې زۀ به خپل قهر او غضب په دوئ نازل کړم او هغوئ به په صحرا کښې تباه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19794, 'Ezekiel 20:14', 'Ezekiel', 20, 14, '&nbsp;بلکې د خپل نوم دپاره ما هغه څۀ وکړل څۀ چې به هغه د هغه قومونو د سترګو د وړاندې د سپکوالى نه وساتى چا چې زۀ وليدلم چې ما هغوئ بهر راوويستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19795, 'Ezekiel 20:15', 'Ezekiel', 20, 15, '&nbsp;خو بيا په صحرا کښې ما دوئ سره قسم وکړو چې زۀ به هغوئ هغه مُلک ته رانۀ ولم کوم چې ما دوئ له ورکړے دے هغه مُلک چې زرخيزه دے، چې د ټولو مُلکونو نه ډېر ښکلے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19796, 'Ezekiel 20:16', 'Ezekiel', 20, 16, '&nbsp;په دې وجه چې هغوئ زما شريعت رد کړو او زما د حکمونو پيروى يې ونۀ کړه او زما د سبت سپکاوے يې وکړو. ځکه چې د هغوئ زړونه خپلو بُتانو ته وقف شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19797, 'Ezekiel 20:17', 'Ezekiel', 20, 17, '&nbsp;خو بيا هم ما دوئ ته د رحم په سترګه وکتل او تباه مې نۀ کړل او نۀ مې هلته په صحرا کښې ختم کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19798, 'Ezekiel 20:18', 'Ezekiel', 20, 18, '&nbsp;ما د هغوئ بچو ته په صحرا کښې وفرمائيل چې، د خپل پلار نيکۀ د رِواج پيروى مۀ کوئ او مۀ د هغوئ په قانون عمل کوئ او مۀ د هغوئ په بُتانو خپل ځان پليتوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19799, 'Ezekiel 20:19', 'Ezekiel', 20, 19, '&nbsp;زۀ مالِک خُدائ ستاسو خُدائ پاک يم. زما د حکمونو پيروى وکړئ او په غور سره زما په قانون عمل وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19800, 'Ezekiel 20:20', 'Ezekiel', 20, 20, '&nbsp;زما د سبت ورځ مقدسه وساتئ، ځکه چې دا به زمونږ دواړو په مينځ کښې د لوظ نښه وى. نو تاسو به په دې پوهه شئ چې زۀ مالِک ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');